// Trusted Cecil metadata only. No inspected assembly is loaded into the CLR.
using System;using System.IO;using System.Linq;using System.Collections.Generic;using System.Web.Script.Serialization;using Mono.Cecil;
static class ScopedVtableAudit
{
 static string Scope(TypeReference t){while(t is TypeSpecification)t=((TypeSpecification)t).ElementType;while(t.DeclaringType!=null)t=t.DeclaringType;var a=t.Scope as AssemblyNameReference;var m=t.Scope as ModuleDefinition;return a!=null?a.FullName:m!=null?m.Assembly.Name.FullName:"?";}
 static string Full(TypeReference t){var p=t as GenericParameter;if(p!=null)return(p.Type==GenericParameterType.Method?"!!":"!")+p.Position;var g=t as GenericInstanceType;if(g!=null)return Full(g.ElementType)+"<"+string.Join(",",g.GenericArguments.Select(Full))+">";var a=t as ArrayType;if(a!=null)return Full(a.ElementType)+"["+new string(',',a.Rank-1)+"]";var b=t as ByReferenceType;if(b!=null)return Full(b.ElementType)+"&";var ptr=t as PointerType;if(ptr!=null)return Full(ptr.ElementType)+"*";var q=t as RequiredModifierType;if(q!=null)return"modreq("+Full(q.ModifierType)+")"+Full(q.ElementType);var o=t as OptionalModifierType;if(o!=null)return"modopt("+Full(o.ModifierType)+")"+Full(o.ElementType);if(t is TypeSpecification)throw new Exception("Unsupported exact diagnostic wrapper "+t.GetType());return"["+Scope(t)+"]"+t.FullName;}
 static string Signature(MethodReference m){return Full(m.DeclaringType)+"::"+m.Name+"("+string.Join(",",m.Parameters.Select(p=>Full(p.ParameterType)))+")->"+Full(m.ReturnType);}
 static int Main(string[] args){try{if(args.Length!=4||File.Exists(args[2]))throw new Exception("raw.dll current.dll fresh.json refs.txt");var rows=new List<object>();foreach(var path in args.Take(2).Concat(File.ReadAllLines(args[3])).Distinct()){using(var a=AssemblyDefinition.ReadAssembly(path,new ReaderParameters{ReadSymbols=false,ReadingMode=ReadingMode.Deferred})){foreach(var n in new[]{"COMLEJJIPLL","LMENEPLIBDK"}){var t=a.MainModule.Types.SingleOrDefault(x=>x.Name==n||x.Name==n+"`1");if(t==null)continue;rows.Add(new{path,name=t.FullName,token=t.MetadataToken.ToUInt32(),flags=(int)t.Attributes,base_type=t.BaseType==null?null:Full(t.BaseType),interfaces=t.Interfaces.Select(x=>Full(x.InterfaceType)).ToArray(),methods=t.Methods.Select(m=>new{token=m.MetadataToken.ToUInt32(),name=m.Name,signature=Signature(m),flags=(int)m.Attributes,impl=(int)m.ImplAttributes,semantics=(int)m.SemanticsAttributes,virtual_method=m.IsVirtual,new_slot=m.IsNewSlot,abstract_method=m.IsAbstract,body=m.HasBody,overrides=m.Overrides.Select(Signature).ToArray()}).ToArray()});}}}File.WriteAllText(args[2],new JavaScriptSerializer{MaxJsonLength=4*1024*1024}.Serialize(new{schema="exact-COMLE-base-vtable-scoped-metadata/v1",rows,game_code_loaded_or_invoked=false}));Console.WriteLine("Metadata only: exact available owners across raw/current/reference inputs written");return 0;}catch(Exception e){Console.Error.WriteLine(e);return 1;}}
}
